@Override
	public void onUpdate() {
		if (getEntityWorld().isRemote) {
	            if (isInWater() && !getEntityWorld().getBlockState(getPosition().down()).getMaterial().isSolid())
					motionY -= 0.2D;

			if (isBeingRidden() && getJawAngle() == 16)
				if (getEntityWorld().getTotalWorldTime() % 20 == 0)
					spawnEatingParticles();
			if (getPearlTimer() == 1)
				spawnSpittingParticles();
			if (getPearlTimer() >= 30)
				if (getEntityWorld().getTotalWorldTime() % 10 == 0)
					spawnMakingParticles();
		}

		if (!getEntityWorld().isRemote) {
			if (getPearlTimer() < 0) {
				if (getEntityWorld().getTotalWorldTime() % 5 == 0)
					checkAreaHere();

				if (getAttackTarget() != null) {
					if (!isBeingRidden() && getJawAngle() < 80) {
						setJawAngle(getJawAngle() + 8);
						if (getEatingHeight() > 0)
							setEatingHeight(0);
					}
					if (isBeingRidden() && getJawAngle() > 16)
						setJawAngle(getJawAngle() - 8);
				}

				if (getAttackTarget() == null) {
					if (!isBeingRidden()) {
						if (getJawAngle() > 0 && getTendrilCount() <= 0)
							setJawAngle(getJawAngle() - 8);
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && getPlacedByPlayer()) {
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {

						setEatingHeight(getEatingHeight() + 1);
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.GENERIC, 0F);
						if (getEatingHeight() == 10 && getPassengers().get(0) != null) {
							setContainedXP(getContainedXP() + Math.round(getXPEaten((EntityLivingBase) getPassengers().get(0)) * 0.5F));
							getPassengers().get(0).setDead();
							if(getContainedXP() >= 10)
								setPearlTimer(PEARL_CREATION_TIME);
							setEatingHeight(0);
							setJawAngle(0);
						}
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && !getPlacedByPlayer())
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.causeMobDamage(this), (float) getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
					}

			} else {
				if (getPearlTimer() >= 0) {
					setPearlTimer(getPearlTimer() - 1);
					if (getEntityWorld().getTotalWorldTime() % 20 == 0 && getPearlTimer() >= 30)
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_DIGEST, SoundCategory.HOSTILE, 1F, 0.8F + rand.nextFloat() * 0.5F);
				}

				if (getPearlTimer() == 0) {
					int quotient = getContainedXP() / 10;
				    int result = getContainedXP() - quotient * 10;
					setContainedXP(result);
					ItemStack pearl = new ItemStack(ItemRegistry.ROCK_SNOT_PEARL, quotient);
					EntityItem item = new EntityItem(world, posX, posY + 0.5D, posZ, pearl);
					item.motionX = item.motionZ = 0D;
					item.motionY = 0.4D;
					world.spawnEntity(item);
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_SPIT, SoundCategory.HOSTILE, 1F, 1F);
				}
			}
		}
		super.onUpdate();
	}

public void checkAreaHere() {
		if (!getEntityWorld().isRemote && getEntityWorld().getDifficulty() != EnumDifficulty.PEACEFUL) {
			List<EntityLivingBase> list = getEntityWorld().getEntitiesWithinAABB(EntityLivingBase.class, proximityBox());
			for (Iterator<EntityLivingBase> iterator = list.iterator(); iterator.hasNext();) {
				EntityLivingBase entity  = iterator.next();
				if (entity != null && !canTarget(entity))
					iterator.remove();
			}
			if (list.isEmpty()) {
				setAttackTarget(null);
				return;
			}
			if (!list.isEmpty()) {
				EntityLivingBase entity = list.get(0);

					if (canSneakPast() && entity.isSneaking())
						return;
					else if (checkSight() && !canEntityBeSeen(entity))
							return;
					else 
						if(getCanShootTendril())
							setAttackTarget((EntityLivingBase) entity);
					if (!isDead && isSingleUse())
						setDead();
			}
		}
	}

public boolean canTarget(EntityLivingBase entity) {
		if((entity instanceof EntityPlayer && getPlacedByPlayer() ||  entity instanceof EntityPlayer && ((EntityPlayer) entity).isSpectator() || entity instanceof EntityPlayer && ((EntityPlayer) entity).isCreative()))
			return false;
		if(entity instanceof EntityRockSnot)
			return false;
		if(entity instanceof EntityLurker)
			return false;
		if(!entity.isNonBoss())
			return false;
		if(!inWater)
			return false;
		return true;
	}

public int getXPEaten(EntityLivingBase entity) {
		int xp = 0;
		if (entity != null) {
			try {
				xp = (Integer) XP_POINTS.invoke(entity, FakePlayerFactory.getMinecraft((WorldServer) getEntityWorld()));
			} catch (Exception e) {
			}
		}
		return xp;
	}

@Override
	public void writeEntityToNBT(NBTTagCompound compound) {
		super.writeEntityToNBT(compound);
		compound.setBoolean("placed_by_player", getPlacedByPlayer());
		compound.setInteger("xpStored", getContainedXP());
	}

@Override
	public void onUpdate() {
		if (!this.getEntityWorld().isRemote)
			if (getParentEntity() == null || getParentEntity().isDead)
				setDead();

		checkCollision();

		if (parent != null && !getExtending()) {
				returnToParent();
			if (getEntityBoundingBox().intersects(parent.getEntityBoundingBox())) {
				if (posX != parent.posX || posZ != parent.posZ)
					setPosition(parent.posX, parent.posY + parent.height * 0.5D, parent.posZ);
				motionX = 0D;
				motionY = 0D;
				motionZ = 0D;

				if (!getEntityWorld().isRemote) {
					if (isBeingRidden() && !parent.isBeingRidden()) {
						Entity entity = getPassengers().get(0);
						entity.startRiding(parent, true);
					}
					setDead();
					parent.setTendrilCount(parent.getTendrilCount() - 1);
				}
			}
		}

		if (parent != null && (!isBeingRidden() && ticksExisted > 20) || parent != null && collidedVertically) {
			if (!getEntityWorld().isRemote) {
				if (getExtending())
					setExtending(false);
			}
		}

		if(getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime()%5 == 0)
			spawnDrips();

		move(MoverType.SELF, motionX, motionY, motionZ);
		motionX *= 1D;
		motionY *= 1D;
		motionZ *= 1D;
		super.onUpdate();
	}

protected Entity checkCollision() {
		if (parent != null) {
			List<EntityLivingBase> list = getEntityWorld().getEntitiesWithinAABB(EntityLivingBase.class, getEntityBoundingBox());
			for (int i = 0; i < list.size(); i++) {
				Entity entity = list.get(i);
				if (entity != null) {
					if (entity instanceof EntityLivingBase && !(entity instanceof EntityRockSnot) && !(entity instanceof EntityRockSnotTendril) && !(entity instanceof EntityLurker) && entity.isNonBoss()) {
						if (entity instanceof EntityPlayer && parent.getPlacedByPlayer() || parent.isBeingRidden())
							return null;
						if (!isBeingRidden()) {
							if (!getEntityWorld().isRemote) {
								entity.startRiding(this, true);
								getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_ATTACH, SoundCategory.HOSTILE, 1F, 1F);
								if (getExtending())
									setExtending(false);
							}
							returnToParent();
						}
					}
				}
			}
		}
		return null;
	}

public void returnToParent() {
		double targetX = parent.posX - posX;
		double targetY = parent.posY + parent.height * 0.5D - posY + height * 0.5D;
		double targetZ = parent.posZ - posZ;
		moveToTarget(targetX, targetY, targetZ, 0.25F);
	}

private void onImpactEntity(EntityHitResult entityRayTrace) {
    Entity entityHit = entityRayTrace.getEntity();
    if (entityHit == null || !entityHit.isAlive()) {
      return;
    }
    Entity owner = getOwner();
    if (owner == entityHit) {
      //player catch it on return 
      dropAsItem();
      return;
    }
    switch (this.boomerangType) {
      case CARRY:
        if (!entityHit.level().isClientSide) {
          entityHit.startRiding(this);
        }
      break;
      case DAMAGE:
        if (entityHit instanceof LivingEntity) {
          LivingEntity live = (LivingEntity) entityHit;
          float damage = Mth.nextFloat(level().random, ConfigRegistry.BOOMERANG_DAMAGE_MIN.get().floatValue(), ConfigRegistry.BOOMERANG_DAMAGE_MAX.get().floatValue());
          boolean attackSucc = live.hurt(level().damageSources().thrown(this, owner), damage);
          if (attackSucc && live.isAlive() == false) {
            //           ("killed one");
          }
        }
      break;
      case STUN:
        //!entityHit.getUniqueID().equals(owner.getUniqueID()) 
        if (entityHit != owner && entityHit instanceof LivingEntity
            && !(entityHit instanceof Player)) {
          LivingEntity live = (LivingEntity) entityHit;
          if (!live.hasEffect(PotionEffectRegistry.STUN)) {
            live.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, ConfigRegistry.BOOMERANG_STUN_SECONDS.get() * Const.TICKS_PER_SEC, 1, false, true, true));
            SoundUtil.playSound(live, SoundEvents.IRON_GOLEM_ATTACK);
          }
        }
      break;
      default:
      break;
    }
  }

@Override
  public void tick() {
    super.tick();
    if (this.tickCount > TICKS_UNTIL_DEATH) {
      dropAsItem();
      return;
    }
    if (this.tickCount > TICKS_UNTIL_RETURN) {
      setIsReturning();
    }
    final BlockPos pos = this.blockPosition();
    Entity owner = getOwner();
    if (owner != null && LevelWorldUtil.distanceBetweenHorizontal(pos, owner.blockPosition()) < 1) {
      dropAsItem();
      return;
    }
    if (hasTriggeredRedstoneAlready() == false && level().isEmptyBlock(pos) == false) {
      tryToggleRedstone(pos);
    }
    tryPickupNearby();
    movementReturnCheck();
  }

private void dropAsItem() {
    if (!boomerangThrown.isEmpty()) {
      Entity owner = getOwner();
      //we have something to drop
      if (owner instanceof Player) {
        Player pl = (Player) owner;
        //try to give it to the player the nicest way possible 
        if (pl.getMainHandItem().isEmpty()) {
          pl.setItemInHand(InteractionHand.MAIN_HAND, boomerangThrown);
          boomerangThrown = ItemStack.EMPTY;
        }
        else {
          owner.spawnAtLocation(boomerangThrown, 0.5F);
          boomerangThrown = ItemStack.EMPTY;
        }
      }
      else {
        ItemStackUtil.drop(level(), this.blockPosition().above(), boomerangThrown);
        boomerangThrown = ItemStack.EMPTY;
      }
    }
    this.remove(RemovalReason.DISCARDED);
  }

public void setOwner(Player ent) {
    this.targetEntity = ent;
    if (ent != null && ent.getUUID() != null) {
      entityData.set(OWNER, ent.getUUID().toString());
    }
  }

private void movementReturnCheck() {
    boolean returning = entityData.get(IS_RETURNING) == 1;
    if (returning) {
      //reverse direction 
      if (this.targetEntity != null) {
        this.moveTowardsTarget();
      }
    }
  }

private void moveTowardsTarget() {
    float newyRot = (float) Math.toRadians(EntityUtil.yawDegreesBetweenPoints(getX(), getY(), getZ(), targetEntity.getX(), targetEntity.getY(), targetEntity.getZ()));
    float newxRot = (float) Math.toRadians(EntityUtil.pitchDegreesBetweenPoints(getX(), getY(), getZ(), targetEntity.getX(), targetEntity.getY(), targetEntity.getZ()));
    this.setYRot(newyRot);
    this.setXRot(newxRot);
    Vec3 moveVec = EntityUtil.lookVector(this.getYRot(), this.getXRot()).scale(SPEED);
    this.setDeltaMovement(
        0.5f * this.getDeltaMovement().x() + 0.5f * moveVec.x,
        0.5f * this.getDeltaMovement().y() + 0.503f * moveVec.y,
        0.5f * this.getDeltaMovement().z() + 0.5f * moveVec.z);
  }

@SuppressWarnings("deprecation")
  private void tryToggleRedstone(final BlockPos pos) {
    Entity owner = getOwner();
    if (owner instanceof Player) {
      try {
        BlockState blockState = level().getBlockState(pos);
        Block block = blockState.getBlock();
        BlockHitResult hitResult = new BlockHitResult(new Vec3(pos.getX(), pos.getY(), pos.getZ()), Direction.UP, pos, false);
        InteractionResult t = blockState.useWithoutItem(level(), (Player) owner, hitResult);
        boolean hasTriggered = t == InteractionResult.SUCCESS;
        if (hasTriggered) {
          this.setRedstoneHasTriggered();
        }
      }
      catch (Throwable e) {
        //since activated can hit any block, be safe
        ModCyclic.LOGGER.error("Error on activate block", e);
      }
    }
  }

@Override
  public void readAdditionalSaveData(CompoundTag tag) {
    entityData.set(OWNER, tag.getString("OWNER"));
    entityData.set(IS_RETURNING, tag.getByte("returning"));
    entityData.set(REDSTONE_TRIGGERED, tag.getByte("REDSTONE_TRIGGERED"));
    if (tag.contains("boomerangItem")) {
      boomerangThrown = ItemStack.parseOptional(this.registryAccess(), tag.getCompound("boomerangItem"));
    } else {
      boomerangThrown = ItemStack.EMPTY;
    }
    super.readAdditionalSaveData(tag);
  }

@Override
  public void addAdditionalSaveData(CompoundTag tag) {
    tag.putString("OWNER", entityData.get(OWNER));
    tag.putByte("returning", entityData.get(IS_RETURNING));
    tag.putByte("REDSTONE_TRIGGERED", entityData.get(REDSTONE_TRIGGERED));
    if (!boomerangThrown.isEmpty()) {
      tag.put("boomerangItem", boomerangThrown.saveOptional(this.registryAccess()));
    }
    super.addAdditionalSaveData(tag);
  }

@Override
  public void releaseUsing(ItemStack stack, Level world, LivingEntity entity, int chargeTimer) {
    int charge = this.getUseDuration(stack, entity) - chargeTimer;
    float percentageCharged = BowItem.getPowerForTime(charge); //never zero, its from [0.03,1];
    if (percentageCharged < 0.1) {
      return; //not enough force to go with any realistic path 
    }

    if (entity instanceof Player == false) {
      return;
    }
    Player player = (Player) entity;
    BoomerangEntity e;
    switch (this.type) {
      case CARRY:
        e = new BoomerangEntityCarry(player, world);
      break;
      case DAMAGE:
        e = new BoomerangEntityDamage(player, world);
      break;
      default:
      case STUN:
        e = new BoomerangEntityStun(player, world);
      break;
    }
    shootMe(world, player, e, 0, percentageCharged * ItemBaseCyclic.VELOCITY_MAX);
    ItemStackUtil.damageItem(player, stack);
    player.setItemInHand(player.getUsedItemHand(), ItemStack.EMPTY);
    e.setBoomerangThrown(stack.copy());
    e.setOwner(player);
  }
